    /// One fixture owns the three semantic domains. Reads never advance them;
    /// publication explicitly admits the actual kept header's UTC sample.
    struct KeptClock {
        epoch: std::time::Instant,
        elapsed_us: AtomicU64,
        wall_ms: AtomicU64,
    }

    impl KeptClock {
        fn new() -> Self {
            Self {
                epoch: std::time::Instant::now(),
                elapsed_us: AtomicU64::new(0),
                wall_ms: AtomicU64::new(0),
            }
        }

        fn advance(&self, elapsed: Duration) {
            self.elapsed_us.fetch_add(
                u64::try_from(elapsed.as_micros()).unwrap(),
                Ordering::SeqCst,
            );
        }

        fn admit_wall(&self, wall_ms: u64) {
            let before = self.wall_ms.swap(wall_ms, Ordering::SeqCst);
            assert!(wall_ms >= before, "publisher UTC regressed");
        }
    }

    impl lamp_bus::SubscriberClock for KeptClock {
        fn now(&self) -> std::time::Instant {
            self.epoch + Duration::from_micros(self.elapsed_us.load(Ordering::SeqCst))
        }

        fn wall_ms(&self) -> u64 {
            self.wall_ms.load(Ordering::SeqCst)
        }
    }

    impl LeaseClock for KeptClock {
        fn monotonic_us(&self) -> u64 {
            // Allows opened_us to be exactly one second old without underflow.
            1_000_001 + self.elapsed_us.load(Ordering::SeqCst)
        }
    }

    struct KeptFixture {
        reader: LeaseReader,
        publisher: lamp_bus::Publisher,
        bus: Bus,
        time: Arc<KeptClock>,
        // Drop subscribers/publisher before removing their owned directory.
        root: Root,
    }

    impl KeptFixture {
        fn new() -> Self {
            static NEXT: AtomicU64 = AtomicU64::new(0);
            let root = Root(PathBuf::from(format!(
                "/tmp/vpl-{}-{}",
                std::process::id(),
                NEXT.fetch_add(1, Ordering::Relaxed)
            )));
            std::fs::create_dir(&root.0).unwrap();
            let time = Arc::new(KeptClock::new());
            let bus = lamp_controls::privacy::selected_bus(Bus::new(&root.0).unwrap());
            let never_looks = bus.clone().rescan_every(Duration::from_secs(3_600));
            let cadence = Arc::clone(&time);
            let mut publisher = never_looks
                .publisher_declared_with_cadence_clock(
                    MicrophonePrivacy::TOPIC,
                    &MicrophonePrivacy::declaration(),
                    "voice",
                    move || lamp_bus::SubscriberClock::now(cadence.as_ref()),
                )
                .unwrap();
            // Complete the publisher's first and only scan before subscribing.
            Self::publish_on(&bus, &time, &mut publisher, 1);
            let reader = LeaseReader::with_fixture_clock(
                &root.0,
                INDICATOR_SUBSCRIBER,
                "host_fixture".into(),
                Arc::clone(&time),
            )
            .unwrap();
            Self { reader, publisher, bus, time, root }
        }

        fn publish_on(
            bus: &Bus,
            time: &KeptClock,
            publisher: &mut lamp_bus::Publisher,
            sequence: u64,
        ) -> Message {
            let at = time.monotonic_us();
            let lease = MicrophonePrivacy {
                stamp: ClockStamp { clock_id: "host_fixture".into(), at_us: at, sequence },
                session_id: publisher.boot().to_owned(),
                controller_boot: "1".repeat(32),
                microphone_generation: 1,
                observed_us: at,
                expires_at_us: at + PRIVACY_FRESH_US,
                permitted: false,
                physical_muted: Some(true),
                no_slide: false,
            };
            let sent = publisher.publish_json(at, &lease).unwrap();
            assert_eq!(sent.delivered, 0, "the kept fixture delivered a datagram");
            // Publication is synchronous. Inspect the actual retained bytes;
            // never rewrite their header, UTC sample, payload or expiry.
            let kept = bus.latest(MicrophonePrivacy::TOPIC).unwrap().unwrap();
            assert_eq!(kept.header.seq, sequence);
            assert_eq!(kept.header.boot, lease.session_id);
            assert_eq!(kept.header.type_name.as_deref(), Some(MicrophonePrivacy::TYPE));
            assert_eq!(kept.parse::<MicrophonePrivacy>().unwrap(), lease);
            time.admit_wall(kept.header.at_unix_ms);
            kept
        }

        fn publish(&mut self, sequence: u64) -> Message {
            Self::publish_on(&self.bus, &self.time, &mut self.publisher, sequence)
        }

        fn read(&mut self, sequence: u64) {
            let read = self.reader.poll().unwrap().expect("the published kept lease");
            assert_eq!(read.stamp.sequence, sequence);
            assert_eq!(self.reader.current.as_ref(), Some(&read));
        }

        fn send_kept_as_datagram(&self, message: &Message) {
            let mut bytes = serde_json::to_vec(&message.header).unwrap();
            bytes.push(b'\n');
            bytes.extend_from_slice(&message.payload);
            let subscribers: Vec<_> = std::fs::read_dir(self.root.0.join("voice/privacy/subs"))
                .unwrap()
                .map(|entry| entry.unwrap().path())
                .collect();
            assert_eq!(subscribers.len(), 1);
            let socket = std::os::unix::net::UnixDatagram::unbound().unwrap();
            assert_eq!(socket.send_to(&bytes, &subscribers[0]).unwrap(), bytes.len());
        }
    }

